/// <summary>
///     The <c>AVAsmmBusRelTableFrm_RelationshipTypeIdFld_Extension</c> class is the extension for <c>smmBusRelTable</c>
/// </summary>
[ExtensionOf(formDataFieldStr(smmBusRelTable, DirPartyRelationship, RelationshipTypeId))]
final class AVAsmmBusRelTableFrm_RelationshipTypeIdFld_Extension
{
}

Method.Source:
/// <summary>
///    AVA <c>validate</c> method.
/// </summary>
/// <returns>
///    <c>boolean</c> as return value
/// </returns>
public boolean validate()
{
    boolean ret;

    ret = next validate();

    if (ret)
    {
        element.getAllowedPartyTypes();
        if (    (element.allowedParentType != DirPartyType::None            || element.allowedChildType != DirPartyType::None)
            &&  (element.allowedParentType != element.dirPartyTable.type()  && element.allowedChildType != element.dirPartyTable.type())    )
        {
            // Relationship %1 is not allowed for type - %2
            return checkFailed(strFmt("@SYS116465", element.dirPartyRelationship.RelationshipTypeId, element.dirPartyTable.type()));
        }
        if (DirRelationshipTypeTable::relationshipTypeToSystemType(element.dirPartyRelationship.RelationshipTypeId) == DirSystemRelationshipType::Prospect)
        {
            // A %1 relationship can only be created by creating a contact person.
            //return checkFailed(strFmt("@SYS116466", enum2str(DirSystemRelationshipType::Prospect)));
            return checkFailed(strFmt("@NDX:NXARelationshipP1ByCreationP2", enum2str(DirSystemRelationshipType::Prospect), "@SYS80138"));
        }
    }

    return ret;
}

/// <summary>
///    AVA <c>modified</c> method.
/// </summary>
public void modified()
{
    DirPartyRelationship        locDirPartyRelationship;
    DirPartyTable               locDirPartyRelationshipParent;
    DirPartyTable               locDirPartyRelationshipChild;
    DirRelationshipTypeTable    locDirRelationshipTypeTable;

    next modified();

    locDirPartyRelationship         = element.dataSource('DirPartyRelationship').cursor();
    locDirPartyRelationshipParent   = element.dataSource('DirPartyRelationshipParent').cursor();
    locDirPartyRelationshipChild    = element.dataSource('DirPartyRelationshipChild').cursor();
    locDirRelationshipTypeTable     = element.dataSource('DirRelationshipTypeTable').cursor();

    locDirRelationshipTypeTable.data(DirRelationshipTypeTable::find(locDirPartyRelationship.RelationshipTypeId));
    locDirPartyRelationship.ChildParty     = locDirPartyRelationshipChild.RecId;
    locDirPartyRelationship.ParentParty    = locDirPartyRelationshipParent.RecId;
}
